package com.emojichathelper;

import java.awt.*;
import net.runelite.client.config.*;

@ConfigGroup(EmojiChatHelperConfig.GROUP)
public interface EmojiChatHelperConfig extends Config
{
	String GROUP = "emojichathelper";

	@ConfigSection(
		name = "Style",
		description = "How the list of matches looks",
		position = 100,
		closedByDefault = true
	)
	String styleSection = "style";

	@ConfigItem(
		keyName = "suggest",
		name = "List matches while typing",
		description = "Lists emoji matching what you're typing: a name after a colon, like :smil, or an emoticon, like :) or Xd. Slack names such as :sweat_smile find emoji too. You type the rest yourself.",
		position = 0
	)
	default boolean suggest()
	{
		return true;
	}

	enum ListPosition
	{
		ABOVE_CHATBOX("Above chatbox"),
		ABOVE_INPUT("Above chat input"),
		MOVABLE("Anywhere (Alt+drag)");

		private final String label;

		ListPosition(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigItem(
		keyName = "listPosition",
		name = "List position",
		description = "Where the list shows. To move it in Anywhere mode, type a colon so it appears, then Alt+drag it.",
		position = 1
	)
	default ListPosition listPosition()
	{
		return ListPosition.ABOVE_CHATBOX;
	}

	@ConfigItem(
		keyName = "maxSuggestions",
		name = "Matches listed",
		description = "Most matches to list.",
		position = 2
	)
	@Range(min = 1, max = 10)
	default int maxSuggestions()
	{
		return 6;
	}

	@ConfigItem(
		keyName = "showOtherName",
		name = "Show emoticon names",
		description = "Shows each emoticon's emoji name beside it.",
		position = 3
	)
	default boolean showOtherName()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showInChat",
		name = "Emoji in chat",
		description = "Shows :names: in chat and overhead text as emoji, as RuneLite's Emojis plugin does.",
		position = 4
	)
	default boolean showInChat()
	{
		return true;
	}

	@ConfigItem(
		keyName = "emoticonsOnly",
		name = "Only emoticons",
		description = "Only lists emoji that have an emoticon, like Xd or <3, and shows the emoticon to type.",
		position = 5
	)
	default boolean emoticonsOnly()
	{
		return false;
	}

	@ConfigItem(
		keyName = "font",
		name = "Font",
		description = "Font and size of the list's text.",
		section = styleSection,
		position = 100
	)
	default FontType font()
	{
		return FontType.SMALL;
	}

	@ConfigItem(
		keyName = "emojiScale",
		name = "Emoji size",
		description = "Scale of the 13 pixel emoji pictures.",
		section = styleSection,
		position = 101
	)
	@Range(min = 1, max = 3)
	default int emojiScale()
	{
		return 1;
	}

	@ConfigItem(
		keyName = "padding",
		name = "Padding",
		description = "Space inside the list's border.",
		section = styleSection,
		position = 102
	)
	@Units(Units.PIXELS)
	@Range(max = 16)
	default int padding()
	{
		return 4;
	}

	@ConfigItem(
		keyName = "rowSpacing",
		name = "Row spacing",
		description = "Extra space between rows.",
		section = styleSection,
		position = 103
	)
	@Units(Units.PIXELS)
	@Range(max = 16)
	default int rowSpacing()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "textShadow",
		name = "Text shadow",
		description = "Draws text with a drop shadow, like the game's.",
		section = styleSection,
		position = 104
	)
	default boolean textShadow()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "backgroundColour",
		name = "Background",
		description = "Background colour. Lower its alpha to make the list see-through.",
		section = styleSection,
		position = 105
	)
	default Color backgroundColour()
	{
		return new Color(14, 12, 10, 235);
	}

	@Alpha
	@ConfigItem(
		keyName = "borderColour",
		name = "Border",
		description = "Border colour. Set its alpha to 0 to hide the border.",
		section = styleSection,
		position = 106
	)
	default Color borderColour()
	{
		return new Color(56, 48, 35);
	}

	@Alpha
	@ConfigItem(
		keyName = "leftColour",
		name = "Left to type",
		description = "The part of a match still to type.",
		section = styleSection,
		position = 107
	)
	default Color leftColour()
	{
		return Color.YELLOW;
	}

	@Alpha
	@ConfigItem(
		keyName = "typedColour",
		name = "Already typed",
		description = "The part of a match already typed.",
		section = styleSection,
		position = 108
	)
	default Color typedColour()
	{
		return new Color(120, 120, 120);
	}

	@Alpha
	@ConfigItem(
		keyName = "nameColour",
		name = "Other matches",
		description = "Matches that don't start with what you've typed, such as typo matches.",
		section = styleSection,
		position = 109
	)
	default Color nameColour()
	{
		return Color.WHITE;
	}

	@Alpha
	@ConfigItem(
		keyName = "emoticonColour",
		name = "Emoticon",
		description = "An emoticon shown beside a name, like Xd.",
		section = styleSection,
		position = 110
	)
	default Color emoticonColour()
	{
		return new Color(90, 220, 120);
	}

	@Alpha
	@ConfigItem(
		keyName = "otherNameColour",
		name = "Emoticon name",
		description = "The emoji name shown beside an emoticon.",
		section = styleSection,
		position = 111
	)
	default Color otherNameColour()
	{
		return new Color(170, 170, 170);
	}
}

package com.emojichathelper;

import com.google.inject.*;
import java.util.*;
import javax.inject.Inject;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.*;
import net.runelite.api.vars.InputType;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.*;
import net.runelite.client.config.*;
import net.runelite.client.eventbus.*;
import net.runelite.client.events.*;
import net.runelite.client.plugins.*;
import net.runelite.client.ui.overlay.*;

/**
 * Lists matching emoji while a :name: or emoticon is typed, and shows :names: in chat as emoji.
 * It uses RuneLite's own emoji names, so what it shows matches RuneLite's Emojis plugin. It never
 * types into the chatbox or changes what is sent.
 */
@PluginDescriptor(
	name = "Emoji Chat Helper",
	description = "Search RuneLite's emoji and emoticons as you type a :name: in chat, the way Slack and Discord do",
	tags = {"emoji", "emojis", "chat", "shortcode", "search", "smiley", "emoticon", "helper"}
)
public class EmojiChatHelperPlugin extends Plugin
{
	/** Shown in the chat input by the Key Remapping plugin while typing is off. */
	private static final String PRESS_ENTER = "Press Enter to Chat";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private EmojiChatHelperConfig config;

	@Inject
	private EmojiIndex index;

	@Inject
	private EmojiIcons icons;

	@Inject
	private ShortcodeList list;

	@Inject
	private ShortcodeOverlay overlay;

	@Inject
	private MovableShortcodeOverlay movableOverlay;

	// Copies of settings read on the client thread every tick and every message.
	private boolean suggest;
	private int maxSuggestions;
	private boolean emoticonsOnly;
	private boolean showInChat;

	@Provides
	EmojiChatHelperConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(EmojiChatHelperConfig.class);
	}

	@Override
	protected void startUp()
	{
		index.load();
		clientThread.invoke(this::applyConfig);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(movableOverlay);
		clientThread.invoke(() -> list.show(null, false, Collections.emptyList()));
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// Config changes arrive on the Swing thread; the list lives on the client thread.
		if (EmojiChatHelperConfig.GROUP.equals(event.getGroup()))
		{
			clientThread.invoke(this::applyConfig);
		}
	}

	private void applyConfig()
	{
		suggest = config.suggest();
		maxSuggestions = config.maxSuggestions();
		emoticonsOnly = config.emoticonsOnly();
		showInChat = config.showInChat();
		list.restyle(new ShortcodeList.Style(config));

		EmojiChatHelperConfig.ListPosition position = config.listPosition();
		overlay.setAboveInput(position == EmojiChatHelperConfig.ListPosition.ABOVE_INPUT);
		overlayManager.remove(overlay);
		overlayManager.remove(movableOverlay);
		overlayManager.add(position == EmojiChatHelperConfig.ListPosition.MOVABLE ? movableOverlay : overlay);

		// Search again on the next tick with the new settings.
		list.show(null, false, Collections.emptyList());
	}

	@Subscribe
	public void onClientTick(ClientTick tick)
	{
		String word = null;
		boolean prompt = false;
		if (suggest && client.getGameState() == GameState.LOGGED_IN)
		{
			int mode = client.getVarcIntValue(VarClientID.MESLAYERMODE);
			prompt = mode == InputType.PRIVATE_MESSAGE.getType();
			if (prompt)
			{
				word = Shortcodes.lastWord(client.getVarcStrValue(VarClientID.MESLAYERINPUT));
			}
			else if (mode == InputType.NONE.getType() && chatInputTakesText())
			{
				word = Shortcodes.lastWord(client.getVarcStrValue(VarClientID.CHATINPUT));
			}
		}
		if (!Objects.equals(word, list.getWord()) || prompt != list.isPrompt())
		{
			list.show(word, prompt, word == null ? Collections.emptyList() : index.search(word, maxSuggestions, emoticonsOnly));
		}
	}

	private boolean chatInputTakesText()
	{
		Widget input = client.getWidget(InterfaceID.Chatbox.INPUT);
		return input != null && !input.isHidden() && !String.valueOf(input.getText()).contains(PRESS_ENTER);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!showInChat)
		{
			return;
		}
		// The same message types RuneLite's Emojis plugin handles.
		switch (event.getType())
		{
			case PUBLICCHAT:
			case MODCHAT:
			case FRIENDSCHAT:
			case CLAN_CHAT:
			case CLAN_GUEST_CHAT:
			case CLAN_GIM_CHAT:
			case PRIVATECHAT:
			case PRIVATECHATOUT:
			case MODPRIVATECHAT:
				break;
			default:
				return;
		}
		MessageNode node = event.getMessageNode();
		String shown = Shortcodes.replace(node.getValue(), this::chatIcon);
		if (shown != null)
		{
			node.setValue(shown);
		}
	}

	@Subscribe
	public void onOverheadTextChanged(OverheadTextChanged event)
	{
		if (!showInChat || !(event.getActor() instanceof Player))
		{
			return;
		}
		String shown = Shortcodes.replace(event.getOverheadText(), this::chatIcon);
		if (shown != null)
		{
			event.getActor().setOverheadText(shown);
		}
	}

	/** The chat icon index for an emoji name, or -1 if it isn't one. */
	private int chatIcon(String name)
	{
		EmojiIndex.Emoji emoji = index.find(name);
		return emoji == null ? -1 : icons.chatIcon(emoji);
	}
}

package com.emojichathelper;

import java.awt.image.*;
import java.util.*;
import javax.inject.*;
import net.runelite.client.game.*;
import net.runelite.client.util.*;

/** Emoji pictures, cut from one sheet, and their chat icons. Client thread. */
@Singleton
class EmojiIcons
{
	static final String SHEET = "emoji.png";
	/** Picture size in pixels, the same as the game's chat icons. */
	static final int SIZE = 13;
	/** Pictures per row of the sheet. */
	static final int COLUMNS = 32;

	@Inject
	private ChatIconManager chatIconManager;

	private BufferedImage sheet;
	private final Map<EmojiIndex.Emoji, BufferedImage> pictures = new HashMap<>();
	/** Kept across plugin restarts, as chat icons can't be unregistered. */
	private final Map<EmojiIndex.Emoji, Integer> chatIcons = new HashMap<>();

	BufferedImage picture(EmojiIndex.Emoji emoji)
	{
		return pictures.computeIfAbsent(emoji, e ->
		{
			if (sheet == null)
			{
				sheet = ImageUtil.loadImageResource(EmojiIcons.class, SHEET);
			}
			BufferedImage picture = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
			picture.getGraphics().drawImage(sheet.getSubimage(e.tile % COLUMNS * SIZE, e.tile / COLUMNS * SIZE, SIZE, SIZE), 0, 0, null);
			return picture;
		});
	}

	/** The index for an {@code <img=>} tag showing the emoji, or -1 if icons aren't loaded yet. */
	int chatIcon(EmojiIndex.Emoji emoji)
	{
		int id = chatIcons.computeIfAbsent(emoji, e -> chatIconManager.registerChatIcon(picture(e)));
		return chatIconManager.chatIconIndex(id);
	}
}

package com.emojichathelper;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.stream.Collectors;
import javax.inject.*;
import lombok.*;

/**
 * RuneLite's emoji: their names, which its Emojis plugin shows as emoji, their emoticons, and
 * Slack's names for them as search keywords. See THIRD_PARTY_NOTICES.md for the data's sources.
 */
@Singleton
class EmojiIndex
{
	static final String FILE = "emoji.txt";
	static final String EMOTICONS = "emoticons.txt";

	@RequiredArgsConstructor
	static final class Emoji
	{
		/** Position in the picture sheet. */
		final int tile;
		final String codepoint;
		final String name;
		/** Short form such as "Xd" or ":)", or null. RuneLite only matches it in this exact case. */
		final String emoticon;
		/**
		 * Slack's names, such as "sweat_smile". Only used to find the emoji: RuneLite doesn't know
		 * them, so they never show as emoji in chat and the list always gives {@link #name}.
		 */
		final List<String> keywords;
	}

	@RequiredArgsConstructor
	static final class Match
	{
		final Emoji emoji;
		/**
		 * 0 exact, 1 prefix, 2 prefix of a later word, 3 substring, 4 one typo, 5 letters in order.
		 */
		final int rank;
		/** Listed by its emoticon rather than its name. */
		final boolean emoticon;

		/** What to type: ":grinning_face:" or "Xd". */
		String typedForm()
		{
			return emoticon ? emoji.emoticon : ":" + emoji.name + ":";
		}

		/**
		 * The rest of the typed form after {@code word}, or null if it doesn't start with it. Case
		 * counts, as RuneLite only matches names and emoticons in their own case.
		 */
		String left(String word)
		{
			String form = typedForm();
			return form.startsWith(word) ? form.substring(word.length()) : null;
		}
	}

	private final List<Emoji> emoji = new ArrayList<>();
	private final Map<String, Emoji> byName = new HashMap<>();

	void load()
	{
		if (!emoji.isEmpty())
		{
			return;
		}
		Map<String, String> emoticons = new HashMap<>();
		for (String line : lines(EMOTICONS))
		{
			String[] parts = line.split(" ", 2);
			emoticons.put(parts[0], parts[1]);
		}
		for (String line : lines(FILE))
		{
			String[] parts = line.split(" ");
			Emoji e = new Emoji(emoji.size(), parts[0], parts[1], emoticons.get(parts[0]),
				Collections.unmodifiableList(Arrays.asList(parts).subList(2, parts.length)));
			emoji.add(e);
			byName.put(e.name, e);
		}
	}

	/** A resource's lines, skipping blank lines and # comments. */
	private static List<String> lines(String file)
	{
		try (InputStream in = EmojiIndex.class.getResourceAsStream(file))
		{
			if (in == null)
			{
				throw new IOException(file + " is missing");
			}
			return new String(in.readAllBytes(), StandardCharsets.UTF_8).lines()
				.filter(line -> !line.isEmpty() && !line.startsWith("#"))
				.collect(Collectors.toList());
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}
	}

	/** All emoji, in sheet order. */
	List<Emoji> all()
	{
		return Collections.unmodifiableList(emoji);
	}

	/** The emoji with this exact RuneLite name, or null. Keywords aren't names. */
	Emoji find(String name)
	{
		return byName.get(name);
	}

	/**
	 * The best matches for the word being typed, at most one per emoji, sorted by rank and then
	 * sheet order. A word starting with a colon is matched against names and keywords; any word is
	 * also matched against emoticons, so a lone colon lists the emoticons that start with one.
	 *
	 * @param emoticonsOnly only emoji that have an emoticon, listed by it
	 */
	List<Match> search(String word, int limit, boolean emoticonsOnly)
	{
		String query = nameQuery(word);
		List<Match> found = new ArrayList<>();
		for (Emoji e : emoji)
		{
			if (emoticonsOnly && e.emoticon == null)
			{
				continue;
			}
			int nameRank = query == null || query.isEmpty() ? -1 : nameRank(e, query);
			int emoticonRank = emoticonRank(e.emoticon, word);
			if (emoticonRank >= 0 && (nameRank < 0 || emoticonRank <= nameRank))
			{
				found.add(new Match(e, emoticonRank, true));
			}
			else if (nameRank >= 0)
			{
				found.add(new Match(e, nameRank, emoticonsOnly));
			}
		}
		found.sort(Comparator.<Match>comparingInt(m -> m.rank).thenComparingInt(m -> m.emoji.tile));
		return found.size() > limit ? new ArrayList<>(found.subList(0, limit)) : found;
	}

	/** The best rank of the emoji's name and keywords, or -1. */
	private static int nameRank(Emoji e, String query)
	{
		int best = rank(e.name, query);
		for (String keyword : e.keywords)
		{
			int rank = rank(keyword, query);
			if (rank >= 0 && (best < 0 || rank < best))
			{
				best = rank;
			}
		}
		return best;
	}

	/**
	 * The lower-cased name after a word's leading colon: "swe" for ":swe", "" for ":". Null if the
	 * word has no leading colon or holds characters no name has, as in "::bank" or ":-)".
	 */
	static String nameQuery(String word)
	{
		if (!word.startsWith(":"))
		{
			return null;
		}
		String name = word.substring(1);
		for (int i = 0; i < name.length(); i++)
		{
			char c = name.charAt(i);
			if (!Character.isLetterOrDigit(c) && c != '_' && c != '+' && c != '-')
			{
				return null;
			}
		}
		return name.toLowerCase(Locale.ROOT);
	}

	/**
	 * 0 if the word is the emoticon, 1 if it starts it (ignoring case), else -1. Emoticons starting
	 * with a letter or digit need two characters typed, so ordinary words don't trigger them.
	 */
	static int emoticonRank(String emoticon, String word)
	{
		if (emoticon == null || word.isEmpty() || word.length() < 2 && Character.isLetterOrDigit(word.charAt(0)))
		{
			return -1;
		}
		if (emoticon.equals(word))
		{
			return 0;
		}
		return emoticon.toLowerCase(Locale.ROOT).startsWith(word.toLowerCase(Locale.ROOT)) ? 1 : -1;
	}

	/**
	 * How well a name matches the query (see {@link Match#rank}), or -1. Substring matches need 3
	 * characters and fuzzy matches 4, to keep short queries from matching everything.
	 */
	static int rank(String name, String query)
	{
		if (name.equals(query))
		{
			return 0;
		}
		if (name.startsWith(query))
		{
			return 1;
		}
		for (int i = 1; i < name.length(); i++)
		{
			if (wordStart(name, i) && name.startsWith(query, i))
			{
				return 2;
			}
		}
		if (query.length() < 3)
		{
			return -1;
		}
		if (name.contains(query))
		{
			return 3;
		}
		if (query.length() < 4)
		{
			return -1;
		}
		if (oneTypo(name, query))
		{
			return 4;
		}
		return inOrder(name, query) ? 5 : -1;
	}

	/** Most letters {@link #inOrder} may skip. */
	static final int IN_ORDER_SKIPS = 3;

	private static boolean wordStart(String name, int i)
	{
		return i == 0 || name.charAt(i - 1) == '_' || name.charAt(i - 1) == '-';
	}

	/**
	 * Whether the query's letters appear in order from the start of a word, skipping at most
	 * {@value #IN_ORDER_SKIPS} letters: "thmbsp" in thumbsup.
	 */
	static boolean inOrder(String name, String query)
	{
		for (int start = 0; start < name.length(); start++)
		{
			if (!wordStart(name, start) || name.charAt(start) != query.charAt(0))
			{
				continue;
			}
			int q = 1;
			int i = start + 1;
			for (; i < name.length() && q < query.length(); i++)
			{
				if (name.charAt(i) == query.charAt(q))
				{
					q++;
				}
			}
			if (q == query.length() && i - start - query.length() <= IN_ORDER_SKIPS)
			{
				return true;
			}
		}
		return false;
	}

	/** Whether a word in the name starts with the query give or take one typo: "simle" for smile. */
	static boolean oneTypo(String name, String query)
	{
		for (int start = 0; start < name.length(); start++)
		{
			if (!wordStart(name, start))
			{
				continue;
			}
			for (int length = query.length() - 1; length <= query.length() + 1; length++)
			{
				if (start + length <= name.length() && oneEdit(name, start, length, query))
				{
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Whether {@code a.substring(from, from + length)} equals {@code b} after at most one change,
	 * insertion, deletion or swap of neighbouring letters. Doesn't allocate, as it runs for every
	 * name on each keystroke.
	 */
	static boolean oneEdit(String a, int from, int length, String b)
	{
		int n = b.length();
		if (Math.abs(length - n) > 1)
		{
			return false;
		}
		int i = 0;
		while (i < length && i < n && a.charAt(from + i) == b.charAt(i))
		{
			i++;
		}
		if (length == n)
		{
			return i == n
				|| a.regionMatches(from + i + 1, b, i + 1, n - i - 1)
				|| i + 1 < n && a.charAt(from + i) == b.charAt(i + 1) && a.charAt(from + i + 1) == b.charAt(i)
				&& a.regionMatches(from + i + 2, b, i + 2, n - i - 2);
		}
		return length > n ? a.regionMatches(from + i + 1, b, i, n - i) : a.regionMatches(from + i, b, i + 1, length - i);
	}
}

